    """Zero the rows and columns crossed by the 2x2 zero marker, keeping 2s."""
    out = [row[:] for row in grid]
    zeros = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 0]
    if not zeros:
        return out
    r0, r1 = min(r for r, _ in zeros), max(r for r, _ in zeros)
    c0, c1 = min(c for _, c in zeros), max(c for _, c in zeros)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r0 <= r <= r1 or c0 <= c <= c1) and grid[r][c] != 2:
                out[r][c] = 0
    return out

